    """Roster (PLAN.md §28): the built-in Off shift, and catalogue version 4 for the roles that exist (roles with HR
    settings get "Roster and shifts" for the whole company; the Platform upgrades its own copy with the same rules)."""
    Shift = apps.get_model("hr", "Shift")
    if not Shift.objects.filter(is_off=True).exists():
        Shift.objects.create(name="Off", code="OFF", is_off=True, colour="muted", order=1000)

    from accounts.access import upgrade_grants
    AccessRole = apps.get_model("accounts", "AccessRole")
    AccessGrant = apps.get_model("accounts", "AccessGrant")
    for role in AccessRole.objects.all():
        have = dict(AccessGrant.objects.filter(role=role).values_list("permission", "scope"))
        new = upgrade_grants(have, role.level or 1, from_version=3)
        for permission, scope in new.items():
            if permission not in have:
                AccessGrant.objects.create(role=role, permission=permission, scope=scope)


